import java.util.*;

class Solution {
    public int largestRectangleArea(int[] heights) {
        Deque<Integer> stack = new ArrayDeque<>();   // indices, heights increasing
        int maxArea = 0;
        for (int i = 0; i <= heights.length; i++) {
            int cur = (i == heights.length) ? 0 : heights[i];   // sentinel 0 flushes the stack
            while (!stack.isEmpty() && cur < heights[stack.peek()]) {
                int height = heights[stack.pop()];
                int left = stack.isEmpty() ? -1 : stack.peek();   // first shorter bar on the left
                maxArea = Math.max(maxArea, height * (i - left - 1));
            }
            stack.push(i);
        }
        return maxArea;
    }
}
